#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const ll INF = 1e18;

class mcf_graph_int_cost {
public:
    struct _edge {
        int to, rev;
        ll cap, cost;
        _edge() {}
        _edge(int to, int rev, ll cap, ll cost) : to(to), rev(rev), cap(cap), cost(cost) {}
    };

    struct edge {
        int from, to;
        ll cap, flow, cost;
        edge() {}
        edge(int from, int to, ll cap, ll flow, ll cost) : from(from), to(to), cap(cap), flow(flow), cost(cost) {}
    };

    mcf_graph_int_cost(int n) : n(n) {
        g.resize(n);
    }

    int add_edge(int from, int to, ll cap, ll cost) {
        int m = pos.size();
        pos.push_back({from, (int)g[from].size()});
        g[from].push_back(_edge(to, (int)g[to].size(), cap, cost));
        g[to].push_back(_edge(from, (int)g[from].size() - 1, 0, -cost));
        return m;
    }

    edge get_edge(int i) {
        _edge &e = g[pos[i].first][pos[i].second];
        _edge &re = g[e.to][e.rev];
        return edge(pos[i].first, e.to, e.cap + re.cap, re.cap, e.cost);
    }

    vector<edge> edges() {
        vector<edge> ret;
        for (int i = 0; i < (int)pos.size(); i++) {
            _edge &e = g[pos[i].first][pos[i].second];
            _edge &re = g[e.to][e.rev];
            ret.push_back(edge(pos[i].first, e.to, e.cap + re.cap, re.cap, e.cost));
        }
        return ret;
    }

    vector<pair<ll, ll>> slope(int s, int t, ll flow_limit = INF) {
        dual.assign(n, 0);
        dist.assign(n, INF);
        pv.assign(n, -1);
        pe.assign(n, -1);
        vis.assign(n, false);

        ll flow = 0;
        ll cost = 0;
        ll prev_cost = -1;
        vector<pair<ll, ll>> result;
        result.push_back({flow, cost});
        while (flow < flow_limit) {
            if (!_dual_ref(s, t)) break;
            ll c = flow_limit - flow;
            int v = t;
            while (v != s) {
                c = min(c, g[pv[v]][pe[v]].cap);
                v = pv[v];
            }
            v = t;
            while (v != s) {
                _edge &e = g[pv[v]][pe[v]];
                e.cap -= c;
                g[v][e.rev].cap += c;
                v = pv[v];
            }
            ll d = -dual[s];
            flow += c;
            cost += c * d;
            if (prev_cost == d) result.pop_back();
            result.push_back({flow, cost});
            prev_cost = cost;
        }
        return result;
    }

    pair<ll, ll> flow(int s, int t, ll flow_limit = INF) {
        auto res = slope(s, t, flow_limit);
        return res.back();
    }

private:
    int n;
    vector<pair<int, int>> pos;
    vector<vector<_edge>> g;
    vector<ll> dual, dist;
    vector<int> pv, pe;
    vector<bool> vis;

    bool _dual_ref(int s, int t) {
        dist.assign(n, INF);
        pv.assign(n, -1);
        pe.assign(n, -1);
        vis.assign(n, false);

        priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
        dist[s] = 0;
        pq.push({0, s});
        while (!pq.empty()) {
            int v = pq.top().second;
            ll d = pq.top().first;
            pq.pop();
            if (vis[v]) continue;
            vis[v] = true;
            if (v == t) break;
            for (int i = 0; i < (int)g[v].size(); i++) {
                _edge &e = g[v][i];
                if (vis[e.to] || e.cap == 0) continue;
                ll cost = e.cost - dual[e.to] + dual[v];
                if (dist[e.to] > dist[v] + cost) {
                    dist[e.to] = dist[v] + cost;
                    pv[e.to] = v;
                    pe[e.to] = i;
                    pq.push({dist[e.to], e.to});
                }
            }
        }
        if (!vis[t]) return false;
        for (int v = 0; v < n; v++) {
            if (vis[v]) {
                dual[v] -= dist[t] - dist[v];
            }
        }
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    ll a1, a2, a3, b1, b2, b3;
    cin >> a1 >> a2 >> a3;
    cin >> b1 >> b2 >> b3;

    mcf_graph_int_cost g(8);
    g.add_edge(0, 1, a1, 0);
    g.add_edge(0, 2, a2, 0);
    g.add_edge(0, 3, a3, 0);
    g.add_edge(4, 7, b1, 0);
    g.add_edge(5, 7, b2, 0);
    g.add_edge(6, 7, b3, 0);
    for (int i = 1; i <= 3; i++) {
        for (int j = 4; j <= 6; j++) {
            ll cost = ((j - i) % 3 == 1) ? 1 : 0;
            g.add_edge(i, j, INF, cost);
        }
    }

    auto res = g.flow(0, 7);
    ll ans1 = res.second;
    ll ans2 = min(a1, b2) + min(a2, b3) + min(a3, b1);
    cout << ans1 << " " << ans2 << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>

using namespace std;

const long long INF = 1e18;

class MinCostFlow {
public:
    struct Edge {
        int to, rev;
        long long cap, cost;
        Edge(int to, int rev, long long cap, long long cost) :
            to(to), rev(rev), cap(cap), cost(cost) {}
    };

    struct EdgeInfo {
        int fr, to;
        long long cap, flow, cost;
        EdgeInfo(int fr, int to, long long cap, long long flow, long long cost) :
            fr(fr), to(to), cap(cap), flow(flow), cost(cost) {}
    };

    MinCostFlow(int n) : n(n), graph(n), dual(n, 0) {}

    void add_edge(int fr, int to, long long cap, long long cost) {
        graph[fr].emplace_back(to, graph[to].size(), cap, cost);
        graph[to].emplace_back(fr, graph[fr].size() - 1, 0, -cost);
    }

    vector<EdgeInfo> edges() {
        vector<EdgeInfo> res;
        for (int v = 0; v < n; ++v) {
            for (auto &e : graph[v]) {
                if (e.cap > 0) {
                    // This edge is forward; find reverse edge
                    auto &re = graph[e.to][e.rev];
                    res.emplace_back(v, e.to, e.cap + re.cap, re.cap, e.cost);
                }
            }
        }
        return res;
    }

    pair<long long, long long> flow(int s, int t, long long flow_limit = INF) {
        auto result = slope(s, t, flow_limit);
        return result.back();
    }

private:
    int n;
    vector<vector<Edge>> graph;
    vector<long long> dual;
    vector<int> pv, pe;

    bool dual_ref(int s, int t) {
        vector<long long> dist(n, INF);
        vector<bool> vis(n, false);
        pv.assign(n, -1);
        pe.assign(n, -1);
        dist[s] = 0;
        priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
        pq.emplace(0, s);
        while (!pq.empty()) {
            auto [d, v] = pq.top();
            pq.pop();
            if (vis[v]) continue;
            vis[v] = true;
            if (v == t) break;
            for (int i = 0; i < (int)graph[v].size(); ++i) {
                auto &e = graph[v][i];
                if (vis[e.to] || e.cap == 0) continue;
                long long cost = e.cost - dual[e.to] + dual[v];
                long long nd = d + cost;
                if (dist[e.to] > nd) {
                    dist[e.to] = nd;
                    pv[e.to] = v;
                    pe[e.to] = i;
                    pq.emplace(nd, e.to);
                }
            }
        }
        if (!vis[t]) return false;
        for (int v = 0; v < n; ++v) {
            if (vis[v]) {
                dual[v] -= dist[t] - dist[v];
            }
        }
        return true;
    }

    vector<pair<long long, long long>> slope(int s, int t, long long flow_limit = INF) {
        fill(dual.begin(), dual.end(), 0);
        long long flow = 0, cost = 0, prev_cost = -1;
        vector<pair<long long, long long>> result;
        result.emplace_back(flow, cost);
        while (flow < flow_limit) {
            if (!dual_ref(s, t)) break;
            long long c = flow_limit - flow;
            for (int v = t; v != s; v = pv[v]) {
                c = min(c, graph[pv[v]][pe[v]].cap);
            }
            for (int v = t; v != s; v = pv[v]) {
                auto &e = graph[pv[v]][pe[v]];
                e.cap -= c;
                graph[v][e.rev].cap += c;
            }
            long long d = -dual[s];
            flow += c;
            cost += c * d;
            if (prev_cost == d) {
                result.pop_back();
            }
            result.emplace_back(flow, cost);
            prev_cost = d;
        }
        return result;
    }
};

int main() {
    const long long INF = 1000000000;
    long long n, a1, a2, a3, b1, b2, b3;
    cin >> n;
    cin >> a1 >> a2 >> a3;
    cin >> b1 >> b2 >> b3;

    MinCostFlow g(8);
    g.add_edge(0, 1, a1, 0);
    g.add_edge(0, 2, a2, 0);
    g.add_edge(0, 3, a3, 0);
    g.add_edge(4, 7, b1, 0);
    g.add_edge(5, 7, b2, 0);
    g.add_edge(6, 7, b3, 0);
    for (int i = 1; i <= 3; ++i) {
        for (int j = 4; j <= 6; ++j) {
            long long cost = ((j - i) % 3 == 1) ? 1 : 0;
            g.add_edge(i, j, INF, cost);
        }
    }

    auto [flow, ans1] = g.flow(0, 7);
    long long ans2 = min(a1, b2) + min(a2, b3) + min(a3, b1);
    cout << ans1 << " " << ans2 << endl;

    return 0;
}

