typedef long long ll;

const ll INF = 1e18;

struct Edge {
    int to, rev;
    ll cap, cost;
    Edge() {}
    Edge(int to, int rev, ll cap, ll cost) : to(to), rev(rev), cap(cap), cost(cost) {}
};

struct EdgeInfo {
    int fr, to;
    ll cap, flow, cost;
    EdgeInfo(int fr, int to, ll cap, ll flow, ll cost) : fr(fr), to(to), cap(cap), flow(flow), cost(cost) {}
};

class MCF {
public:
    int n;
    vector<vector<Edge>> g;
    vector<pair<int,int>> pos;
    vector<int> pv, pe;
    vector<ll> dist;

    MCF(int n) : n(n), g(n) {}

    int add_edge(int fr, int to, ll cap, ll cost) {
        int m = pos.size();
        pos.emplace_back(fr, g[fr].size());
        g[fr].emplace_back(to, g[to].size(), cap, cost);
        g[to].emplace_back(fr, g[fr].size()-1, 0, -cost);
        return m;
    }

    EdgeInfo get_edge(int i) {
        auto &e = g[pos[i].first][pos[i].second];
        auto &re = g[e.to][e.rev];
        return EdgeInfo(pos[i].first, e.to, e.cap + re.cap, re.cap, e.cost);
    }

    vector<EdgeInfo> edges() {
        vector<EdgeInfo> res;
        for (int i = 0; i < (int)pos.size(); ++i) {
            auto &e = g[pos[i].first][pos[i].second];
            auto &re = g[e.to][e.rev];
            res.emplace_back(pos[i].first, e.to, e.cap + re.cap, re.cap, e.cost);
        }
        return res;
    }

    bool _bellman_ford(int s, int t) {
        dist.assign(n, INF);
        pv.assign(n, -1);
        pe.assign(n, -1);
        dist[s] = 0;
        for (int _ = 0; _ < n-1; ++_) {
            bool updated = false;
            for (int v = 0; v < n; ++v) {
                if (dist[v] == INF) continue;
                for (int i = 0; i < (int)g[v].size(); ++i) {
                    auto &e = g[v][i];
                    if (e.cap == 0) continue;
                    ll nd = dist[v] + e.cost;
                    if (dist[e.to] > nd) {
                        dist[e.to] = nd;
                        pv[e.to] = v;
                        pe[e.to] = i;
                        updated = true;
                    }
                }
            }
            if (!updated) break;
        }
        return dist[t] != INF;
    }

    vector<pair<ll,ll>> slope(int s, int t, ll flow_limit = INF) {
        ll flow = 0, cost = 0;
        ll prev_cost = -1;
        vector<pair<ll,ll>> result;
        result.emplace_back(flow, cost);
        while (flow < flow_limit) {
            if (!_bellman_ford(s, t)) break;
            ll c = flow_limit - flow;
            int v = t;
            while (v != s) {
                c = min(c, g[pv[v]][pe[v]].cap);
                v = pv[v];
            }
            v = t;
            while (v != s) {
                auto &e = g[pv[v]][pe[v]];
                e.cap -= c;
                g[v][e.rev].cap += c;
                v = pv[v];
            }
            ll d = dist[t];
            flow += c;
            cost += c * d;
            if (prev_cost == d) result.pop_back();
            result.emplace_back(flow, cost);
            prev_cost = d;
        }
        return result;
    }

    pair<ll,ll> flow(int s, int t, ll flow_limit = INF) {
        auto res = slope(s, t, flow_limit);
        return res.back();
    }
};

