#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <utility>
using namespace std;
typedef long long ll;

class MCFGraph {
public:
    int n;
    vector<pair<int,int>> pos;
    vector<vector<int>> to, rev;
    vector<vector<ll>> cap, cost;
    vector<ll> dual;
    vector<int> pv, pe;

    MCFGraph(int n) : n(n), to(n), rev(n), cap(n), cost(n), dual(n, 0) {}

    int add_edge(int fr, int to_, ll cap_, ll cost_) {
        int m = pos.size();
        pos.emplace_back(fr, to[fr].size());
        to[fr].push_back(to_);
        rev[fr].push_back(to[to_].size());
        cap[fr].push_back(cap_);
        cost[fr].push_back(cost_);
        to[to_].push_back(fr);
        rev[to_].push_back(to[fr].size() - 1);
        cap[to_].push_back(0);
        cost[to_].push_back(-cost_);
        return m;
    }

    struct Edge {
        int fr, to;
        ll cap, flow, cost;
        Edge(int fr, int to, ll cap, ll flow, ll cost) : fr(fr), to(to), cap(cap), flow(flow), cost(cost) {}
    };

    Edge get_edge(int i) {
        int fr = pos[i].first;
        int idx = pos[i].second;
        int to_ = to[fr][idx];
        int rev_idx = rev[fr][idx];
        ll cap_ = cap[fr][idx];
        ll rev_cap = cap[to_][rev_idx];
        ll cost_ = cost[fr][idx];
        return Edge(fr, to_, cap_ + rev_cap, rev_cap, cost_);
    }

    vector<Edge> edges() {
        vector<Edge> res;
        for (int i = 0; i < (int)pos.size(); i++) {
            int fr = pos[i].first;
            int idx = pos[i].second;
            int to_ = to[fr][idx];
            int rev_idx = rev[fr][idx];
            ll cap_ = cap[fr][idx];
            ll rev_cap = cap[to_][rev_idx];
            ll cost_ = cost[fr][idx];
            res.emplace_back(fr, to_, cap_ + rev_cap, rev_cap, cost_);
        }
        return res;
    }

    bool _dual_ref(int s, int t) {
        const ll INF = 1e18;
        vector<ll> dist(n, INF);
        vector<int> pv(n, -1), pe(n, -1);
        vector<bool> vis(n, false);
        dist[s] = 0;
        priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
        pq.push(make_pair(0, s));
        while (!pq.empty()) {
            pair<ll,int> top = pq.top(); pq.pop();
            ll d = top.first;
            int v = top.second;
            if (vis[v]) continue;
            vis[v] = true;
            if (v == t) break;
            for (int i = 0; i < (int)to[v].size(); i++) {
                if (vis[to[v][i]] || cap[v][i] == 0) continue;
                ll nd = d + cost[v][i] - dual[to[v][i]] + dual[v];
                if (dist[to[v][i]] > nd) {
                    dist[to[v][i]] = nd;
                    pv[to[v][i]] = v;
                    pe[to[v][i]] = i;
                    pq.push(make_pair(nd, to[v][i]));
                }
            }
        }
        if (!vis[t]) return false;
        for (int v = 0; v < n; v++) {
            if (vis[v]) {
                dual[v] -= dist[t] - dist[v];
            }
        }
        this->pv = pv;
        this->pe = pe;
        return true;
    }

    vector<pair<ll,ll>> slope(int s, int t, ll flow_limit = 1e18) {
        dual.assign(n, 0);
        ll flow = 0, cost = 0;
        ll prev_cost = -1;
        vector<pair<ll,ll>> result;
        result.push_back(make_pair(flow, cost));
        while (flow < flow_limit) {
            if (!_dual_ref(s, t)) break;
            ll c = flow_limit - flow;
            int v = t;
            while (v != s) {
                c = min(c, cap[pv[v]][pe[v]]);
                v = pv[v];
            }
            v = t;
            while (v != s) {
                int idx = pe[v];
                cap[pv[v]][idx] -= c;
                int rev_idx = rev[pv[v]][idx];
                cap[v][rev_idx] += c;
                v = pv[v];
            }
            ll d = -dual[s];
            flow += c;
            cost += c * d;
            if (prev_cost == d) {
                result.pop_back();
            }
            result.push_back(make_pair(flow, cost));
            prev_cost = d;
        }
        return result;
    }

    pair<ll,ll> flow(int s, int t, ll flow_limit = 1e18) {
        vector<pair<ll,ll>> res = slope(s, t, flow_limit);
        return res.back();
    }
};

