#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const ll INF = 1e18;

struct MinCostFlow {
    struct Edge {
        int to, rev;
        ll cap, cost;
        Edge(int to, int rev, ll cap, ll cost) : to(to), rev(rev), cap(cap), cost(cost) {}
    };

    int n;
    vector<vector<Edge>> g;
    vector<ll> dual;
    vector<int> pv, pe;

    MinCostFlow(int n) : n(n), g(n), dual(n), pv(n), pe(n) {}

    void add_edge(int fr, int to, ll cap, ll cost) {
        g[fr].emplace_back(to, (int)g[to].size(), cap, cost);
        g[to].emplace_back(fr, (int)g[fr].size() - 1, 0, -cost);
    }

    bool dual_ref(int s, int t) {
        vector<ll> dist(n, INF);
        vector<bool> vis(n, false);
        dist[s] = 0;
        priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
        pq.emplace(0, s);
        while (!pq.empty()) {
            auto [d, v] = pq.top(); pq.pop();
            if (vis[v]) continue;
            vis[v] = true;
            if (v == t) break;
            for (int i = 0; i < (int)g[v].size(); ++i) {
                Edge &e = g[v][i];
                if (vis[e.to] || e.cap == 0) continue;
                ll cost = e.cost - dual[e.to] + dual[v];
                ll nd = d + cost;
                if (dist[e.to] > nd) {
                    dist[e.to] = nd;
                    pv[e.to] = v;
                    pe[e.to] = i;
                    pq.emplace(nd, e.to);
                }
            }
        }
        if (!vis[t]) return false;
        for (int v = 0; v < n; ++v) {
            if (vis[v]) dual[v] -= dist[t] - dist[v];
        }
        return true;
    }

    pair<ll, ll> flow(int s, int t, ll flow_limit = INF) {
        ll flow = 0, cost = 0;
        while (flow < flow_limit) {
            if (!dual_ref(s, t)) break;
            ll c = flow_limit - flow;
            for (int v = t; v != s; v = pv[v]) {
                c = min(c, g[pv[v]][pe[v]].cap);
            }
            for (int v = t; v != s; v = pv[v]) {
                Edge &e = g[pv[v]][pe[v]];
                e.cap -= c;
                g[v][e.rev].cap += c;
            }
            ll d = -dual[s];
            flow += c;
            cost += c * d;
        }
        return {flow, cost};
    }
};

