    ll max_lost = 0;
    struct State {
        int mask;
        ll a[3];
        ll b[3];
        ll lost;
    };
    stack<State> st;
    State init;
    init.mask = (1<<6)-1;
    copy(a, a+3, init.a);
    copy(b, b+3, init.b);
    init.lost = 0;
    st.push(init);
