            if (cur.lost > max_lost) max_lost = cur.lost;
            continue;
        }
        for (int i = 0; i < 6; ++i) {
            if (cur.mask & (1<<i)) {
                int ai = ways[i].first;
                int bi = ways[i].second;
                ll add = min(cur.a[ai], cur.b[bi]);
