    vector<pair<int,int>> ways = {{0,2}, {1,0}, {2,1}, {0,0}, {1,1}, {2,2}};
    sort(ways.begin(), ways.end());
    int max_lost = 0;
    do {
        vector<int> a_copy = a;
        vector<int> b_copy = b;
        int lost = 0;
        for (auto& p : ways) {
            int ai = p.first;
            int bi = p.second;
            int add = min(a_copy[ai], b_copy[bi]);
            a_copy[ai] -= add;
            b_copy[bi] -= add;
            lost += add;
        }
        if (lost > max_lost) max_lost = lost;
    } while (next_permutation(ways.begin(), ways.end()));
    return max_lost;
}

