#include <iostream>
#include <vector>
#include <algorithm>

class RPS {
private:
    std::vector<int> first;
    std::vector<int> second;
public:
    RPS(const std::vector<int>& f, const std::vector<int>& s) : first(f), second(s) {}

    int max_wins() const {
        std::vector<int> sec = second;
        sec.push_back(second[0]); // sec = [second[0], second[1], second[2], second[0]]
        int total = 0;
        for (int i = 0; i < 3; ++i) {
            total += std::min(first[i], sec[i+1]);
        }
        return total;
    }

    int min_wins() const {
        std::vector<int> first_copy = first;
        std::vector<int> sec = {second[2], second[0], second[1], second[2]};
        for (int i = 0; i < 3; ++i) {
            if (first_copy[i] > 0) {
                int diff = std::min(first_copy[i], sec[i]);
                first_copy[i] -= diff;
                sec[i] -= diff;
                if (first_copy[i] > 0) {
                    diff = std::min(first_copy[i], sec[i+1]);
                    first_copy[i] -= diff;
                    sec[i+1] -= diff;
                }
            }
        }
        int total = 0;
        for (int i = 0; i < 3; ++i) {
            total += first_copy[i];
        }
        return total;
    }
};

int main() {
    int round;
    std::cin >> round;
    std::vector<int> first(3), second(3);
    for (int i = 0; i < 3; ++i) {
        std::cin >> first[i];
    }
    for (int i = 0; i < 3; ++i) {
        std::cin >> second[i];
    }
