    cin >> n >> M;

    // D[x] will store divisors d (2 <= d <= x/2) of x
    vector<vector<int>> D(n + 1);
    for (int d = 2; d <= n; ++d) {
        for (int dst = 2 * d; dst <= n; dst += d) {
            D[dst].push_back(d);
        }
    }

    vector<long long> F(n + 1, 0);
    if (n >= 1) F[1] = 1;
    if (n >= 2) F[2] = 2;

    for (int x = 3; x <= n; ++x) {
        F[x] = (2 * F[x - 1] + 1) % M;
