        for (int d : D[x]) {
            // condition 2 <= d <= x-2 is automatically true for x >= 4,
            // but we keep it for safety (for x=3, D[3] is empty anyway)
            if (d >= 2 && d <= x - 2) {
                long long diff = F[x / d] - F[(x - 1) / d];
                // ensure non-negative modulo
                S = (S + (diff % M + M) % M) % M;
            }
        }
        F[x] = (F[x] + S) % M;
    }

    cout << F[n] % M << endl;
    return 0;
}

