from math import sqrt
import sys

def contributions(i, mem, sq):
    for f in range(2, sq):
        yield mem[i // f]
    for j in range(1, i // sq + 1):
        yield (i // j - i // (j + 1)) * mem[j]

def main():
    n, mod = map(int, sys.stdin.readline().split())
    mem = [0, 1]
    su = 1
    for i in range(2, n + 1):
        sq = int(sqrt(i)) + 1
        cur = su
        for term in contributions(i, mem, sq):
            cur = (cur + term) % mod
        su = (su + cur) % mod
        mem.append(cur)
    print(mem[-1])

if __name__ == "__main__":
    main()

