sieve = [True] * limit
sieve[0] = False
sieve[1] = False
for i in range(2, int(limit ** 0.5) + 1):
    if sieve[i]:
        for j in range(i * i, limit, i):
            sieve[j] = False
primes = [i for i in range(2, limit) if sieve[i]]

def factor(n):
    d = {}
    for p in primes:
        if p * p > n:
            break
        if n % p == 0:
            cnt = 0
            while n % p == 0:
                n //= p
                cnt += 1
            d[p] = cnt
    if n > 1:
        d[n] = 1
    return d

def divisors(n):
    divs = [1]
    for p, e in factor(n).items():
        divs = [old * p ** k for old in divs for k in range(e + 1)]
    return divs

def process(n, m):
    f = {0: 0, 1: 1, 2: 2}
    for i in range(3, n + 1):
        total = 2 * f[i - 1]
        for x in divisors(i):
            if 2 <= x <= i:
                total += f[i // x] - f[(i - 1) // x]
        f[i] = total % m
    return f[n]

n, m = [int(x) for x in input().split()]
print(process(n, m))

