#include <iostream>
#include <vector>
#include <map>
#include <cmath>
#include <algorithm>

using namespace std;

const int LIMIT = 6000;
vector<int> primes;

void sieve() {
    vector<bool> is_prime(LIMIT, true);
    is_prime[0] = is_prime[1] = false;
    for (int i = 2; i * i < LIMIT; ++i) {
        if (is_prime[i]) {
            for (int j = i * i; j < LIMIT; j += i) {
                is_prime[j] = false;
            }
        }
    }
    for (int i = 2; i < LIMIT; ++i) {
        if (is_prime[i]) primes.push_back(i);
    }
}

map<int, int> factor(int n) {
    map<int, int> res;
    for (int p : primes) {
        if (p * p > n) break;
        if (n % p == 0) {
            int cnt = 0;
            while (n % p == 0) {
                n /= p;
                ++cnt;
            }
            res[p] = cnt;
        }
    }
    if (n > 1) res[n] = 1;
    return res;
}

vector<long long> divisors(int n) {
    map<int, int> fac = factor(n);
    vector<long long> divs = {1};
    for (auto &entry : fac) {
        int p = entry.first;
        int e = entry.second;
        vector<long long> new_divs;
        long long pk = 1;
        for (int k = 0; k <= e; ++k) {
            for (long long old : divs) {
                new_divs.push_back(old * pk);
            }
            pk *= p;
        }
        divs = new_divs;
    }
    return divs;
}

long long process(int n, int m) {
    vector<long long> f(n + 1);
    f[0] = 0;
    f[1] = 1;
    f[2] = 2;
    for (int i = 3; i <= n; ++i) {
        long long total = (2 * f[i - 1]) % m;
        vector<long long> divs = divisors(i);
        for (long long x : divs) {
            if (x >= 2 && x <= i) {
                long long term = f[i / x] - f[(i - 1) / x];
                term %= m;
                if (term < 0) term += m;
                total = (total + term) % m;
            }
        }
        f[i] = total;
    }
    return f[n];
}

int main() {
    sieve();
    int n, m;
    cin >> n >> m;
    cout << process(n, m) << endl;
    return 0;
}

