    vector<int> divs;
    divs.push_back(1);
    int temp = n;
    for (int p : primes) {
        if (p * p > temp) break;
        if (temp % p == 0) {
            vector<int> new_divs = divs;
            int power = 1;
            while (temp % p == 0) {
                temp /= p;
                power *= p;
                for (int base : divs) {
                    new_divs.push_back(base * power);
                }
            }
            divs = new_divs;
        }
    }
    if (temp > 1) {
        int sz = divs.size();
        for (int i = 0; i < sz; i++) {
            divs.push_back(divs[i] * temp);
        }
    }
    return divs;
}

long long process(int n, int m) {
    vector<long long> f(n + 1);
    f[0] = 0;
    if (n >= 1) f[1] = 1;
    if (n >= 2) f[2] = 2;
