#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>

using namespace std;

// Precompute primes up to 6000
vector<int> get_primes() {
    vector<int> primes;
    for (int p = 2; p < 6000; ++p) {
        bool is_prime = true;
        for (int q = 2; q * q <= p; ++q) {
            if (p % q == 0) {
                is_prime = false;
                break;
            }
        }
        if (is_prime) primes.push_back(p);
    }
    return primes;
}

// Factorize n using the given primes list
vector<pair<int, int>> factor(int n, const vector<int>& primes) {
    vector<pair<int, int>> factors;
    for (int p : primes) {
        if (p * p > n) break;
        if (n % p == 0) {
            int cnt = 0;
            while (n % p == 0) {
                n /= p;
                ++cnt;
            }
            factors.push_back({p, cnt});
        }
    }
    if (n > 1) {
        factors.push_back({n, 1});
    }
    return factors;
}

// Generate all divisors from prime factorization
void gen_divisors(const vector<pair<int, int>>& factors, int idx, int current, vector<int>& divs) {
    if (idx == (int)factors.size()) {
        divs.push_back(current);
        return;
    }
    int p = factors[idx].first;
    int e = factors[idx].second;
    int pow = 1;
    for (int k = 0; k <= e; ++k) {
        gen_divisors(factors, idx + 1, current * pow, divs);
        pow *= p;
    }
}

vector<int> divisors(int n, const vector<int>& primes) {
    vector<pair<int, int>> fac = factor(n, primes);
    vector<int> divs;
    gen_divisors(fac, 0, 1, divs);
    return divs;
}

long long process(int n, int m, const vector<int>& primes) {
    vector<long long> f(n + 1);
    f[0] = 0;
    f[1] = 1;
    f[2] = 2;
    for (int i = 3; i <= n; ++i) {
        long long val = (2 * f[i - 1]) % m;
        vector<int> divs = divisors(i, primes);
        for (int x : divs) {
            if (x >= 2 && x <= i) {
                long long diff = f[i / x] - f[(i - 1) / x];
                diff = (diff % m + m) % m; // ensure non-negative
                val = (val + diff) % m;
            }
        }
        f[i] = val % m;
    }
    return f[n];
}

int main() {
    int n, m;
    cin >> n >> m;
    vector<int> primes = get_primes();
    long long result = process(n, m, primes);
    cout << result << endl;
    return 0;
}

