    n, m = map(int, data)
    dp = [0] * (n + 1)
    dp[n] = 1

    def get(k):
        if k <= n:
            return dp[k]
        return 0

    for i in range(n - 1, 0, -1):
        val = (2 * dp[i + 1]) % m
        for j in range(2, n // i + 1):
            val = (val + dp[i * j] - get((i + 1) * j)) % m
        dp[i] = val

    sys.stdout.write(str((get(1) - get(2)) % m) + "\n")

if __name__ == "__main__":
    main()

