// integer square root (floor)
long long isqrt(long long x) {
    long long r = (long long) sqrt(x);
    while ((r + 1) * (r + 1) <= x) ++r;
    while (r * r > x) --r;
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    long long n, mod;
    cin >> n >> mod;

    vector<long long> mem;
    mem.push_back(0);
    mem.push_back(1);
    long long su = 1;

    for (long long i = 2; i <= n; ++i) {
        long long sq = isqrt(i) + 1;
        long long cur = su;

        // first loop: large divisors (f from 2 to sq-1)
        long long f = 2;
        while (f < sq) {
            cur = (cur + mem[i / f]) % mod;
            ++f;
        }

        // second loop: small divisors (j from 1 to i//sq)
        long long be = i;
        long long j = 1;
        long long limit = i / sq;
        while (j <= limit) {
            long long nxt = i / (j + 1);
            long long add = ((be - nxt) % mod) * (mem[j] % mod) % mod;
            cur = (cur + add) % mod;
            be = nxt;
            ++j;
        }

        su = (su + cur) % mod;
        mem.push_back(cur);
    }

    cout << mem.back() << '\n';

    return 0;
}

