using namespace std;

const long long MOD = 1000000007LL;

long long modpow(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T = 1;
    while (T--) {
        int P, K;
        cin >> P >> K;

        if (K == 0) {
            cout << modpow(P, P - 1, MOD) << '\n';
            continue;
        }
        if (K == 1) {
            cout << modpow(P, P, MOD) << '\n';
            continue;
        }

        vector<int> f(P, 0);
        vector<int> c(P, 0);

        for (int i = 0; i < P; ++i) {
            if (f[i]) continue;
            int cnt = 1;
            int u = i;
            f[u] = 1;
            int next = (1LL * K * u) % P;
            while (!f[next]) {
                u = next;
                f[u] = 1;
                cnt++;
                next = (1LL * K * u) % P;
            }
            c[cnt]++;
        }

        long long ans = 1;
        for (int i = 2; i < P; ++i) {
            if (c[i] != 0) {
                long long cnt = 1LL * i * c[i] + 1;
                ans = (ans * modpow(cnt, c[i], MOD)) % MOD;
            }
        }
        cout << ans << '\n';
    }
    return 0;
}

