const long long MOD = 1000000007;

long long pow_mod(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int P, K;
    cin >> P >> K;

    if (K == 0) {
        cout << pow_mod(P, P - 1, MOD) << '\n';
        return 0;
    }
    if (K == 1) {
        cout << pow_mod(P, P, MOD) << '\n';
        return 0;
    }

    vector<int> k(P);
    for (int i = 0; i < P; ++i) {
        k[i] = (static_cast<long long>(K) * i) % P;
    }

    vector<bool> visited(P, false);
    vector<int> counts(P + 1, 0); // extra space for safety

    for (int start = 0; start < P; ++start) {
        if (visited[start]) continue;
        int length = 1;
        int node = start;
        visited[node] = true;
        while (!visited[k[node]]) {
            node = k[node];
            visited[node] = true;
            ++length;
        }
        ++counts[length];
    }

    long long ans = 1;
    for (int i = 2; i < P; ++i) {
        if (counts[i] > 0) {
            long long factor = static_cast<long long>(i) * counts[i] + 1;
            ans = (ans * pow_mod(factor, counts[i], MOD)) % MOD;
        }
