#include <iostream>
#include <algorithm>
#include <cmath>
using namespace std;

typedef long long ll;

const ll MOD = 1000000007LL;

// Fast modular exponentiation: base^exp % mod
ll pow_mod(ll base, ll exp, ll mod) {
    ll result = 1 % mod;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

class Solver {
public:
    ll p, k;

    Solver(ll p, ll k) : p(p), k(k) {}

    ll order() {
        ll p_ = p, k_ = k;
        ll order = 1;
        ll cur = k_;
        while (cur != 1) {
            cur = (cur * k_) % p_;
            order++;
        }
        return order;
    }

    ll answer() {
        if (k == 0) {
            return pow_mod(p, p - 1, MOD);
        }
        if (k == 1) {
            return pow_mod(p, p, MOD);
        }
        ll ord = order();
        return pow_mod(p, (p - 1) / ord, MOD);
    }
};

int main() {
    ll p, k;
    cin >> p >> k;
    Solver solver(p, k);
    cout << solver.answer() << endl;
    return 0;
}

