// Replace first occurrence of 'from' with 'to' in s
string replace_first(string s, const string& from, const string& to) {
    size_t pos = s.find(from);
    if (pos != string::npos) {
        s.replace(pos, from.length(), to);
    }
    return s;
}

string transform(string s) {
    // Process 'at' rule
    size_t idx = s.find("at");
    if (idx == 0) {
        // first 'at' at beginning: replace the next 'at' in the remainder
        string rest = s.substr(2);
        rest = replace_first(rest, "at", "@");
        s = s.substr(0, 2) + rest;
    } else if (idx != string::npos) {
        // replace first occurrence
        s = s.substr(0, idx) + "@" + s.substr(idx + 2);
    }
    // else no 'at' at all

    // Process 'dot' rule: replace all, then fix borders
    // Replace all "dot" with "."
    size_t pos = 0;
    while ((pos = s.find("dot", pos)) != string::npos) {
        s.replace(pos, 3, ".");
        pos += 1; // move past the inserted '.'
    }

    if (!s.empty() && s[0] == '.') {
        s = "dot" + s.substr(1);
    }
    if (!s.empty() && s.back() == '.') {
        s = s.substr(0, s.length() - 1) + "dot";
    }
    return s;
}

