    int i = 0;
    bool first_at_handled = false;

    // Handle first 'at'
    while (i < n - 1) {
        if (s[i] == 'a' && s[i+1] == 't') {
            if (!first_at_handled) {
                if (i == 0) {
                    // Keep it as 'at', skip to next
                    first_at_handled = true;
                    i += 2;
                    continue;
                } else {
                    // Replace this 'at' with '@'
                    s[i] = '@';
                    s.erase(i+1, 1); // remove 't'
                    n--;
                    first_at_handled = true;
                    i++;
                    continue;
                }
            } else {
                // Already handled first occurrence, break
                break;
            }
        }
        i++;
    }

    // Handle all 'dot' -> '.'
    i = 0;
    while (i < n - 2) {
        if (s[i] == 'd' && s[i+1] == 'o' && s[i+2] == 't') {
            s[i] = '.';
            s.erase(i+1, 2); // remove 'o' and 't'
            n -= 2;
            i++;
        } else {
            i++;
        }
    }

    // Fix borders after dot replacements
    if (!s.empty() && s[0] == '.') {
        s[0] = 'd';
        s.insert(1, "o");
        s.insert(2, "t");
        n += 2;
    }
    if (!s.empty() && s.back() == '.') {
        s.back() = 't';
        s.insert(s.size()-1, 1, 'o');
        s.insert(s.size()-1, 1, 'd');
        n += 2;
    }

    cout << s << endl;
    return 0;
}

