vector<long long> subset_sums(const vector<long long>& arr, long long m) {
    unordered_set<long long> res;
    res.insert(0);
    for (long long x : arr) {
        // Copy current sums to a vector for iteration (to avoid modifying set while iterating)
        vector<long long> cur(res.begin(), res.end());
        unordered_set<long long> new_sums;
        for (long long s : cur) {
            new_sums.insert((s + x) % m);
        }
        // Merge new sums into res
        for (long long ns : new_sums) {
            res.insert(ns);
        }
    }
    vector<long long> result(res.begin(), res.end());
    sort(result.begin(), result.end());
    return result;
}

