vector<int> subset_sums_mod(const vector<int>& arr, int mod) {
    int n = arr.size();
    vector<int> res;
    int total_masks = 1 << n;
    for (int mask = 0; mask < total_masks; ++mask) {
        long long sum = 0;
        for (int j = 0; j < n; ++j) {
            if (mask & (1 << j)) {
                sum += arr[j];
            }
        }
        res.push_back(static_cast<int>(sum % mod));
    }
    sort(res.begin(), res.end());
    res.erase(unique(res.begin(), res.end()), res.end());
    return res;
}

