unordered_set<int> subset_sums(const vector<int>& arr, int k) {
    unordered_set<int> sums;
    for (int x : arr) {
        x %= k;
        unordered_set<int> new_sums;
        for (int y : sums) {
            new_sums.insert((x + y) % k);
        }
        sums.insert(x);
        sums.insert(new_sums.begin(), new_sums.end());
    }
    return sums;
}

