    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j <= m; ++j) {
            ll a = 0;
            for (int k = 0; k <= n; ++k) {
                a = (a + S_dp[i][k][j]) % mod;
                SS_dp[i][j][k] = a;
            }
        }
    }

