    int m = n * (n - 1) / 2;

    // dp[i][j][k] : number of permutations of size i with j inversions and last element = k
    vector<vector<vector<int>>> dp(n + 1, vector<vector<int>>(m + 1, vector<int>(n + 1, 0)));
    dp[1][0][1] = 1;

    for (int i = 1; i < n; ++i) {
        auto& cur = dp[i];
        auto& nxt = dp[i + 1];
