            auto& row = cur[j];
            for (int k = 0; k <= n; ++k) {
                int val = row[k];
                if (val == 0) continue;
                // insert new largest element at the end
                nxt[j + i][i + 1] = (nxt[j + i][i + 1] + val) % mod;
                int base = j + i - 1;
                for (int l = 0; l < i; ++l) {
                    nxt[base - l][k] = (nxt[base - l][k] + val) % mod;
                }
            }
        }
        // modulo reduction for nxt
        for (int j = 0; j <= m; ++j) {
            auto& row = nxt[j];
            for (int k = 0; k <= n; ++k) {
                row[k] %= mod;
            }
        }
    }

    // S_dp[i][k][j] = sum_{t=0..j} dp[i][t][k] mod mod
    vector<vector<vector<int>>> S_dp(n + 1, vector<vector<int>>(n + 1, vector<int>(m + 1, 0)));
    for (int i = 0; i <= n; ++i) {
        for (int k = 0; k <= n; ++k) {
