    c = factorials(n, mod)
    tables = build_tables(n, mod)
    ans = 0
    for i in range(1, n):
        ans = (ans + score(tables[i], mod, c[i + 1])) % mod
    return ans

def main():
    n, m = map(int, input().split())
    print(solve(n, m))

if __name__ == "__main__":
