void solve() {
    long long n, mod;
    cin >> n >> mod;
    if (n == 1) {
        cout << 0 << endl;
        return;
    }
    // suffix products: suff[i] = product from i to n modulo mod
    vector<long long> suff(n + 2, 1);
    suff[n + 1] = 1;
    for (long long i = n; i >= 1; --i) {
        suff[i] = (suff[i + 1] * i) % mod;
    }
    vector<long long> lst = {1};
    long long ans = 0;
    for (long long i = 2; i <= n; ++i) {
        long long len_lst = lst.size();
        long long n_len = (i - 1) * i / 2 + 1;
        vector<long long> nz(n_len, 0);
        vector<long long> d(len_lst + 1, 0);
        // compute d from right to left
        for (long long idx = len_lst - 1; idx >= 0; --idx) {
            d[idx] = (d[idx + 1] + lst[idx]) % mod;
        }
        // compute nz
        for (long long nz_idx = 0; nz_idx < n_len; ++nz_idx) {
            long long L = max(0LL, nz_idx + 1 - i);
            long long R = min(len_lst - 1, nz_idx);
            nz[nz_idx] = (d[L] - d[R + 1]) % mod;
            if (nz[nz_idx] < 0) nz[nz_idx] += mod;
        }
        // compute e and f
        vector<long long> e(len_lst + 2, 0);
        vector<long long> f(len_lst + 2, 0);
        for (long long pos = 0; pos < len_lst; ++pos) {
            e[pos + 1] = (e[pos] + d[pos]) % mod;
            f[pos + 1] = (f[pos] - pos * d[pos]) % mod;
            if (f[pos + 1] < 0) f[pos + 1] += mod;
        }
        // compute temp
        long long temp = 0;
        long long start = max(0LL, len_lst - i);
        for (long long j = start; j < len_lst - 2; ++j) {
            long long L = j + 2;
            long long term1 = (e[len_lst] - e[L]) % mod;
            if (term1 < 0) term1 += mod;
            long long term2 = (f[len_lst] - f[L]) % mod;
            if (term2 < 0) term2 += mod;
            temp = (temp + (term1 * (i + 1 + j) + term2) % mod * lst[j]) % mod;
        }
        for (long long j = 0; j < len_lst - i; ++j) {
            long long L = j + 2;
            long long R2 = i + j;
            long long term1 = (e[R2 + 1] - e[L]) % mod;
            if (term1 < 0) term1 += mod;
            long long term2 = (f[R2 + 1] - f[L]) % mod;
            if (term2 < 0) term2 += mod;
            temp = (temp + (term1 * (i + 1 + j) + term2) % mod * lst[j]) % mod;
        }
        // update ans with product from i+1 to n
        long long prod = suff[i + 1];
        ans = (ans + temp * prod) % mod;
        lst = nz;
    }
    cout << ans % mod << endl;
