    }

    int a = min(n, m);
    int b = max(n, m);

    if (a == 1) {
        int base = (b / 6) * 6;
        int rem = b % 6;
        if (rem == 5) return base + 4;
        else if (rem == 4) return base + 2;
        else return base;
    }

    if (a == 2 && b == 7) return 12;

