#include <iostream>
#include <map>

using namespace std;
typedef long long ll;

ll num1(int n) {
    static map<int, ll> cache;
    if (cache.find(n) != cache.end()) return cache[n];
    if (n < 0) return 0;
    if (n < 2) return 1;
    ll r = 0;
    for (int i = 0; i < n; ++i) {
        r += num1(i) * num1(n - 1 - i);
    }
    cache[n] = r;
    return r;
}

ll num2(int n, int h) {
    static map<pair<int,int>, ll> cache;
    auto key = make_pair(n, h);
    if (cache.find(key) != cache.end()) return cache[key];
    if (n < 0 || h <= 0) { cache[key] = 0; return 0; }
    // condition: n >= 2^(h-1) -> return 0
    if (h-1 >= 0 && h-1 < 31 && n >= (1LL << (h-1))) {
        cache[key] = 0;
        return 0;
    }
    if (n < 2) { cache[key] = 1; return 1; }
    if (n < h) { ll res = num1(n); cache[key] = res; return res; }
    ll r = 0;
    for (int i = 0; i < n; ++i) {
        r += num2(i, h-1) * num2(n-1-i, h-1);
    }
    cache[key] = r;
    return r;
}

