using namespace std;

long long compute(int n, int h) {
    // Catalan numbers
    vector<long long> cat(n + 1, 0);
    cat[0] = 1;
    if (n >= 1) cat[1] = 1;
    for (int m = 2; m <= n; ++m) {
        long long total = 0;
        for (int i = 0; i < m; ++i) {
            total += cat[i] * cat[m - 1 - i];
        }
        cat[m] = total;
    }

    // DP table: dp[n][h] for n nodes and height <= h
    // We'll use a 2D vector, initialized to 0.
    vector<vector<long long>> dp(n + 1, vector<long long>(h + 1, 0));

    // Helper function to get dp value with conditions
    auto get_dp = [&](int nn, int hh) -> long long {
        // Compute 2^(hh-1) safely
        long long max_nodes;
        if (hh - 1 >= 60) {
            max_nodes = LLONG_MAX;
        } else {
            max_nodes = 1LL << (hh - 1);
        }
        if (nn < 0 || hh <= 0 || nn >= max_nodes) return 0;
        if (nn < 2) return 1;
        if (nn < hh) return cat[nn];
        return dp[nn][hh];
    };

    // Fill DP bottom-up
    for (int hh = 1; hh <= h; ++hh) {
        for (int nn = 0; nn <= n; ++nn) {
            // Compute 2^(hh-1) safely
            long long max_nodes;
            if (hh - 1 >= 60) {
                max_nodes = LLONG_MAX;
            } else {
                max_nodes = 1LL << (hh - 1);
            }
            if (nn < 0 || hh <= 0 || nn >= max_nodes) continue;
            if (nn < 2) {
                dp[nn][hh] = 1;
            } else if (nn < hh) {
                dp[nn][hh] = cat[nn];
            } else {
                long long total = 0;
                for (int i = 0; i < nn; ++i) {
                    long long left = get_dp(i, hh - 1);
                    long long right = get_dp(nn - 1 - i, hh - 1);
                    total += left * right;
                }
                dp[nn][hh] = total;
            }
        }
    }

    return cat[n] - dp[n][h];
}

int main() {
    int n, h;
    cin >> n >> h;
    cout << compute(n, h) << endl;
    return 0;
}

