using namespace std;

typedef unsigned long long ull;

const ull BASE = 1000000000ULL; // 10^9

struct BigInt {
    vector<ull> digits; // little-endian, each digit < BASE

    BigInt() : digits(1, 0) {}
    BigInt(ull x) {
        if (x == 0) digits.push_back(0);
        else {
            while (x) {
                digits.push_back(x % BASE);
                x /= BASE;
            }
        }
    }
    BigInt(const BigInt& other) : digits(other.digits) {}

    BigInt& operator=(const BigInt& other) {
        digits = other.digits;
        return *this;
    }

    bool is_zero() const {
        return digits.size() == 1 && digits[0] == 0;
    }

    // compare absolute values (assume both positive)
    bool operator<(const BigInt& other) const {
        if (digits.size() != other.digits.size())
            return digits.size() < other.digits.size();
        for (int i = (int)digits.size() - 1; i >= 0; --i) {
            if (digits[i] != other.digits[i])
                return digits[i] < other.digits[i];
        }
        return false;
    }

    BigInt operator+(const BigInt& other) const {
        BigInt res;
        res.digits.clear();
        ull carry = 0;
        size_t max_len = max(digits.size(), other.digits.size());
        for (size_t i = 0; i < max_len || carry; ++i) {
            ull sum = carry;
            if (i < digits.size()) sum += digits[i];
            if (i < other.digits.size()) sum += other.digits[i];
            res.digits.push_back(sum % BASE);
            carry = sum / BASE;
        }
        return res;
    }

    // assume *this >= other (both positive)
    BigInt operator-(const BigInt& other) const {
        BigInt res;
        res.digits.clear();
        ull borrow = 0;
        size_t max_len = digits.size();
        for (size_t i = 0; i < max_len; ++i) {
            ull diff = digits[i] - borrow;
            if (i < other.digits.size()) diff -= other.digits[i];
            else diff -= 0;
            if (diff > digits[i]) { // underflow
                diff += BASE;
                borrow = 1;
            } else {
                borrow = 0;
            }
            res.digits.push_back(diff);
        }
        // remove leading zeros
        while (res.digits.size() > 1 && res.digits.back() == 0)
            res.digits.pop_back();
        return res;
    }

    BigInt operator*(const BigInt& other) const {
        BigInt res;
        res.digits.assign(digits.size() + other.digits.size(), 0);
        for (size_t i = 0; i < digits.size(); ++i) {
            ull carry = 0;
            for (size_t j = 0; j < other.digits.size() || carry; ++j) {
                ull prod = res.digits[i + j] + carry;
                if (j < other.digits.size())
                    prod += digits[i] * other.digits[j];
                res.digits[i + j] = prod % BASE;
                carry = prod / BASE;
            }
        }
        while (res.digits.size() > 1 && res.digits.back() == 0)
            res.digits.pop_back();
        return res;
    }

    // multiply by small integer (0 <= x < BASE)
    BigInt operator*(ull x) const {
        if (x == 0) return BigInt(0);
        BigInt res;
        res.digits.clear();
        ull carry = 0;
        for (size_t i = 0; i < digits.size() || carry; ++i) {
            ull prod = carry;
            if (i < digits.size()) prod += digits[i] * x;
            res.digits.push_back(prod % BASE);
            carry = prod / BASE;
        }
        return res;
    }

    void print() const {
        if (digits.empty()) { cout << 0; return; }
        cout << digits.back();
        for (int i = (int)digits.size() - 2; i >= 0; --i) {
            string s = to_string(digits[i]);
            while (s.length() < 9) s = "0" + s;
            cout << s;
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, h;
    cin >> n >> h;

    vector<BigInt> s(n + 1);
    s[0] = BigInt(1);
    for (int m = 1; m <= n; ++m) {
        BigInt sum(0);
        for (int k = 0; k < m; ++k) {
            sum = sum + s[k] * s[m - 1 - k];
        }
        s[m] = sum;
    }

    vector<BigInt> t = s;

    for (int iter = 0; iter < h; ++iter) {
        vector<BigInt> nt(n + 1);
        for (int m = 1; m <= n; ++m) {
            BigInt cs(0), ct(0);
            for (int k = 0; k < m; ++k) {
                cs = cs + s[k] * t[m - 1 - k];
                ct = ct + t[k] * t[m - 1 - k];
            }
            nt[m] = cs * 2 - ct; // 2*cs - ct
        }
        t = nt;
    }

    t[n].print();
    cout << endl;

    return 0;
}

